1	//! Event-driven state recorder.
2	//!
3	//! Implements [`EventConsumer`] to update persistent state in response to
4	//! step lifecycle events. This decouples state recording from the orchestrator
5	//! — the orchestrator emits events, the recorder consumes them.
6	
7	use std::sync::{Arc, Mutex};
8	use std::time::Duration;
9	
10	use crate::logging::events::{BivvyEvent, EventConsumer};
11	
12	use super::store::{StateStore, StepStatus};
13	
14	/// Records step results by consuming events from the event bus.
15	///
16	/// Listens for `StepCompleted` and `StepSkipped` events and updates the
17	/// underlying [`StateStore`] accordingly. Uses `Arc<Mutex<StateStore>>`
18	/// so the caller can share access for reads and saves.
19	pub struct StateRecorder {
20	    store: Arc<Mutex<StateStore>>,
21	}
22	
23	impl StateRecorder {
24	    /// Create a new recorder wrapping a shared state store.
25	    pub fn new(store: Arc<Mutex<StateStore>>) -> Self {
26	        Self { store }
27	    }
28	
29	    /// Get the shared state store reference.
30	    pub fn store(&self) -> &Arc<Mutex<StateStore>> {
31	        &self.store
32	    }
33	}
34	
35	impl EventConsumer for StateRecorder {
36	    fn on_event(&mut self, event: &BivvyEvent) {
37	        match event {
38	            BivvyEvent::StepCompleted {
39	                name,
40	                success,
41	                duration_ms,
42	                ..
43	            } => {
44	                let status = if *success {
45	                    StepStatus::Success
46	                } else {
47	                    StepStatus::Failed
48	                };
49	                if let Ok(mut store) = self.store.lock() {
50	                    store.record_step_result(name, status, Duration::from_millis(*duration_ms));
51	                }
52	            }
53	            BivvyEvent::StepSkipped { name, .. } => {
54	                if let Ok(mut store) = self.store.lock() {
55	                    store.record_step_result(name, StepStatus::Skipped, Duration::ZERO);
56	                }
57	            }
58	            _ => {}
59	        }
60	    }
61	}
