2	
3	use std::fs;
4	use std::path::PathBuf;
5	
6	use anyhow::{Context, Result};
7	
8	use super::{SessionId, SessionMetadata};
9	
10	/// A complete session record.
11	#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
12	pub struct Session {
13	    /// Unique session identifier.
14	    pub id: SessionId,
15	    /// Session metadata.
16	    pub metadata: SessionMetadata,
17	}
18	
19	/// Storage for sessions.
20	pub struct SessionStore {
21	    path: PathBuf,
22	}
23	
24	impl SessionStore {
25	    /// Create a new session store.
26	    pub fn new(path: impl Into<PathBuf>) -> Self {
27	        Self { path: path.into() }
28	    }
29	
30	    /// Ensure the store directory exists.
31	    fn ensure_dir(&self) -> Result<()> {
32	        fs::create_dir_all(&self.path)
33	            .with_context(|| format!("Failed to create session store at {:?}", self.path))
34	    }
35	
36	    /// Get the path for a session file.
37	    fn session_path(&self, id: &SessionId) -> PathBuf {
38	        self.path.join(format!("{}.json", id))
39	    }
40	
41	    /// Save a session.
42	    pub fn save(&self, session: &Session) -> Result<()> {
43	        self.ensure_dir()?;
44	        let path = self.session_path(&session.id);
45	        let json = serde_json::to_string_pretty(session)?;
46	        fs::write(&path, json).with_context(|| format!("Failed to write session to {:?}", path))
47	    }
48	
49	    /// Load a session by ID.
50	    pub fn load(&self, id: &SessionId) -> Result<Session> {
51	        let path = self.session_path(id);
52	        let json =
53	            fs::read_to_string(&path).with_context(|| format!("Session not found: {:?}", path))?;
54	        serde_json::from_str(&json).context("Failed to parse session")
55	    }
56	
57	    /// Get the most recent session.
58	    pub fn get_latest(&self) -> Result<Option<Session>> {
59	        let sessions = self.list_recent(1)?;
60	        Ok(sessions.into_iter().next())
61	    }
62	
63	    /// List recent sessions.
64	    pub fn list_recent(&self, limit: usize) -> Result<Vec<Session>> {
65	        self.ensure_dir()?;
66	
67	        let mut sessions = Vec::new();
68	        for entry in fs::read_dir(&self.path)? {
69	            let entry = entry?;
70	            let path = entry.path();
71	            if path.extension().is_some_and(|e| e == "json") {
72	                if let Ok(json) = fs::read_to_string(&path) {
73	                    if let Ok(session) = serde_json::from_str::<Session>(&json) {
74	                        sessions.push(session);
75	                    }
76	                }
77	            }
78	        }
79	
80	        // Sort by timestamp descending
81	        sessions.sort_by(|a, b| b.id.timestamp().cmp(&a.id.timestamp()));
82	        sessions.truncate(limit);
83	
84	        Ok(sessions)
85	    }
86	
87	    /// Clean up old sessions (keep last N).
88	    pub fn cleanup(&self, keep: usize) -> Result<usize> {
89	        let sessions = self.list_recent(usize::MAX)?;
90	        let mut removed = 0;
91	
92	        for session in sessions.into_iter().skip(keep) {
93	            let path = self.session_path(&session.id);
94	            if fs::remove_file(&path).is_ok() {
95	                removed += 1;
96	            }
97	        }
98	
99	        Ok(removed)
100	    }
101	
102	    /// Get the store path.
103	    pub fn path(&self) -> &PathBuf {
104	        &self.path
105	    }
106	}
