12	/// Re-claim the terminal foreground process group.
13	///
14	/// After a child process exits, the parent shell (especially zsh) may
15	/// reclaim the foreground group, leaving bivvy as a background process.
16	/// Any subsequent terminal I/O would then trigger SIGTTOU/SIGTTIN.
17	/// This function re-asserts bivvy's ownership of the foreground group.
18	///
19	/// Safe to call multiple times — no-op if already foreground or if
20	/// `/dev/tty` is unavailable (non-TTY, CI, piped environments).
21	#[cfg(unix)]
22	pub(crate) fn claim_foreground() {
23	    // SAFETY: libc calls to open/close /dev/tty and set the foreground
24	    // process group. SIGTTOU is already ignored (main.rs) so tcsetpgrp
25	    // won't suspend us even if we're currently backgrounded.
26	    unsafe {
27	        let tty_fd = libc::open(c"/dev/tty".as_ptr(), libc::O_RDWR);
28	        if tty_fd >= 0 {
29	            libc::tcsetpgrp(tty_fd, libc::getpgrp());
30	            libc::close(tty_fd);
31	        }
32	    }
33	}
34	
35	/// Drain any buffered terminal input to prevent queued keypresses
36	/// from triggering unintended actions after a child process exits.
37	#[cfg(unix)]
38	pub(crate) fn drain_input() {
39	    use std::io::Read;
40	    // Set stdin to non-blocking, read and discard, restore blocking
41	    unsafe {
42	        let fd = libc::STDIN_FILENO;
43	        let flags = libc::fcntl(fd, libc::F_GETFL);
44	        if flags >= 0 {
45	            libc::fcntl(fd, libc::F_SETFL, flags | libc::O_NONBLOCK);
46	            let mut buf = [0u8; 1024];
47	            while std::io::stdin().read(&mut buf).unwrap_or(0) > 0 {}
48	            libc::fcntl(fd, libc::F_SETFL, flags);
49	        }
50	    }
51	}
