1	//! Gap checker for requirement evaluation.
2	//!
3	//! The `GapChecker` evaluates whether system-level requirements are met,
4	//! caching results within a run to avoid redundant command executions.
5	
6	mod deps;
7	mod evaluator;
8	mod network;
9	
10	use crate::requirements::probe::EnvironmentProbe;
11	use crate::requirements::registry::RequirementRegistry;
12	use crate::requirements::status::{GapResult, RequirementStatus};
13	use crate::steps::resolved::ResolvedStep;
14	use deps::DependencyResolver;
15	use evaluator::RequirementEvaluator;
16	use std::collections::{HashMap, HashSet};
17	use std::path::Path;
18	
19	/// Checks whether requirements are satisfied on the system.
20	///
21	/// Caches results per-run so the same requirement checked multiple times
22	/// only executes commands once.
23	pub struct GapChecker<'a> {
24	    evaluator: RequirementEvaluator<'a>,
25	    resolver: DependencyResolver<'a>,
26	    cache: HashMap<String, RequirementStatus>,
27	}
28	
29	impl<'a> GapChecker<'a> {
30	    /// Create a new gap checker.
31	    pub fn new(
32	        registry: &'a RequirementRegistry,
33	        probe: &'a EnvironmentProbe,
34	        project_root: &Path,
35	    ) -> Self {
36	        Self {
37	            evaluator: RequirementEvaluator {
38	                registry,
39	                probe,
40	                project_root: project_root.to_path_buf(),
41	            },
42	            resolver: DependencyResolver { registry, probe },
43	            cache: HashMap::new(),
44	        }
45	    }
46	
47	    /// Check all requirements for a step, returning only non-satisfied gaps.
48	    ///
49	    /// `provided_requirements` is authoritative — if the environment says
50	    /// a requirement is provided, skip the check regardless of what the
51	    /// step's requires list says. Until environments exist, callers pass `None`.
52	    pub fn check_step(
53	        &mut self,
54	        step: &ResolvedStep,
55	        provided: Option<&HashSet<String>>,
56	    ) -> Vec<GapResult> {
57	        let mut gaps = Vec::new();
58	        for req_name in &step.requires {
59	            if let Some(provided_set) = provided {
60	                if provided_set.contains(req_name) {
61	                    continue;
62	                }
63	            }
64	
65	            let status = self.check_one(req_name);
66	            if !status.is_satisfied() {
67	                gaps.push(GapResult {
68	                    requirement: req_name.clone(),
69	                    status,
70	                });
71	            }
72	        }
73	        gaps
74	    }
75	
76	    /// Check a single requirement, using cache when available.
77	    pub fn check_one(&mut self, requirement: &str) -> RequirementStatus {
78	        if let Some(cached) = self.cache.get(requirement) {
79	            return cached.clone();
80	        }
81	
82	        let status = self.evaluator.evaluate(requirement);
83	        self.cache.insert(requirement.to_string(), status.clone());
84	        status
85	    }
86	
87	    /// Invalidate a cached result for a specific requirement.
88	    pub fn invalidate(&mut self, requirement: &str) {
89	        self.cache.remove(requirement);
90	    }
91	
92	    /// Invalidate all cached results.
93	    pub fn invalidate_all(&mut self) {
94	        self.cache.clear();
95	    }
96	
97	    /// Resolve the install dependency chain for a requirement.
98	    ///
99	    /// Returns the ordered list of requirements that need to be installed,
100	    /// with dependencies before dependents. Max depth 5, detects circular deps.
101	    pub fn resolve_install_deps(&self, requirement: &str) -> Result<Vec<String>, String> {
102	        self.resolver.resolve(requirement)
103	    }
104	
